-- VRFW bb_pages, online grid (enjoy_team_select_menu network variant: quick match and private rooms).
-- This script ALSO runs for the offline grid: the framework decides online from the
-- game's state (BB mode byte 4 / network predicate) and answers 0 rows offline. The framework's build makes the Estadio BB table longer and regroups / sorts it, so
-- the grid the game builds would show other teams than an unmodded player's. On open, the framework rebuilds the live
-- grid with the game's own teams in the game's order (CMND_VRFW_BB_PAGE_RETAIL) and turns its page keys off: the
-- online list is the retail one. (Private rooms with the same mod set on both sides: planned, needs a channel to
-- compare the mod sets.) Globals only; nothing runs at chunk load.
VRFW_BBP_ONLINE = {
  RETAIL = 3292142377,
  SLOT = 2572859650,
  LOG = 3661580131,
  GRID = 106197494 --[[vs01_43_enjoy_team_select_emblem_icon]],
  LOCK = 892105257 --[[mainmenu90_30_lock_icon]],
}

function VRFW_BBP_OnlineRetail(why)
  local O = VRFW_BBP_ONLINE
  local ok, rows = pcall(funcLuaCommand, O.RETAIL)
  -- the slots already created get their emblems again (the rest are set up by the game from the rebuilt records)
  local n = funcLuaMenuCommand(1175615627, O.GRID) or 0
  -- rows 0 = the framework found the team select offline (this script also runs for the offline grid): nothing to do
  if ok and type(rows) == "number" and rows > 0 and SetupEmblemIcon ~= nil then
    for i = 0, n - 1 do
      local team, unlocked, check, lock = funcLuaCommand(O.SLOT, i)
      if type(team) == "number" and team ~= 0 then
        pcall(SetupEmblemIcon, i, team, unlocked == true, check == true)
      end
      -- the rows of the "win it to unlock it" rule are open online: no padlock
      if type(lock) == "number" and lock >= 0 and unlocked == true then
        pcall(funcLuaMenuCommand, 711242136, O.LOCK, lock, false)
      elseif type(lock) == "number" and lock >= 0 then
        -- a locked slot's padlock gets the closed look: an instance the rebuild moved here may still have the gold
        -- "press to unlock" one (_lock_icon01_off / _on, anime Active stopped, type lock)
        pcall(funcLuaMenuCommand, 3405944500, O.LOCK, 868450029 --[[_lock_icon01_off]], true, lock)
        pcall(funcLuaMenuCommand, 3405944500, O.LOCK, 3251826719 --[[_lock_icon01_on]], false, lock)
        pcall(funcLuaMenuCommand, 3781155141, O.LOCK, lock, 1286797620 --[[Active]], 2, 2274335502 --[[lock]])
      end
    end
  end
  pcall(funcLuaCommand, O.LOG, "VRFW bb_pages", string.format("network variant %s: retail rows %s (0 = offline: extended list), slots %d", why, tostring(rows), n))
end

do
  local init = OnInit
  function OnInit(...)
    local r = table.pack(init(...))
    local ok, err = pcall(VRFW_BBP_OnlineRetail, "open")
    if not ok then
      pcall(funcLuaCommand, VRFW_BBP_ONLINE.LOG, "VRFW bb_pages", "online error " .. tostring(err))
    end
    return table.unpack(r, 1, r.n)
  end
end
